import{_ as n,l as o,o as e,c as l,v as t,p as s,x as i,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"链式复制","description":"","frontmatter":{"title":"链式复制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/chain-replication.md","filePath":"cs/chain-replication.md","lastUpdated":1789023840000}'),h={name:"cs/chain-replication.md"};function _(u,a,m,f,A,T){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="链式复制" tabindex="-1">链式复制 <a class="header-anchor" href="#链式复制" aria-label="Permalink to &quot;链式复制&quot;">​</a></h1><div class="epigraph"><p>写从头流向尾，读只在尾。尾是提交点：尾上的值已沿链持久。头死了从后继接，尾死了前任升尾。</p><footer>—— 据 van Renesse and Schneider, Chain Replication for Supporting High Throughput and Availability, OSDI 2004 整理</footer></div><p>上一课<a href="/cs/primary-backup-failover">主备</a>是星形：主向所有备同步。缺口是<strong>吞吐</strong>：主的出站带宽随副本数线性涨。链式复制把副本排成一条线，主（头）只发给一个后继。本课不重写 fencing 纪元。后课 quorum 是另一套相交集合，不是链。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 副本要线性一致读写。链：\\(H \\to \\cdots \\to T\\)。写请求到头，沿链转发，尾应答客户端（或沿链回 ack，视实现）。读到尾。因为每写必须流过整链才在尾可见，尾上的状态是已提交前缀；读尾得到线性化点在尾应答处。</p><p>缺口：链中段故障如何拆链再接，且不丢已在尾的写、不让未到尾的写冒充提交。需要配置主（通常小规模共识或目录）宣布新链。</p><p><span class="marginnote">CRAQ 让读分摊到链上节点但用版本问询，本课点名：纯 CR 读集中在尾，读吞吐是瓶颈。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>头故障：后继变头，未完全传播的写由客户端重试（要幂等）。尾故障：前任变尾，其状态已是原尾的前缀，提交点不后退。中段：前驱改连后继，需保证 FIFO 与未完成写的重传。</p>',9)),(e(),s(c,null,{default:i(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%22%E5%86%99%22%5D%20--%3E%20H%5B%22%E5%A4%B4%22%5D%0A%20%20H%20--%3E%20M%5B%22%E4%B8%AD%22%5D%0A%20%20M%20--%3E%20T%5B%22%E5%B0%BE%22%5D%0A%20%20T%20--%3E%20ACK%5B%22%E6%8F%90%E4%BA%A4%22%5D%0A%20%20R%5B%22%E8%AF%BB%22%5D%20--%3E%20T%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与主备：主备主发送 \\(n-1\\) 份；链每节点发送 1 份。写延迟是链长倍的 RTT，不是星形的一个 RTT 等最慢备——权衡方向不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>线性化：写的线性化点可放在尾处理处；读尾看到的是已在尾的写集合前缀。若读头，会看见未提交写，破坏线性一致。历史与 Herlihy–Wing 对齐靠「只读尾」。</p><p>配置主自己必须强一致，否则两条链同时有效，等价双主。链再长也把 CAP 的 C 押在配置面上。故障时缩短链，可用副本变少，直到配置主补节点。</p><p>本课不把 Kafka ISR、日志分段写成链式复制定理：它们借鉴「提交点在高水位」，拓扑不是单链转发每个字节。后课日志会自己讲。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CRAQ 协议全文，不引入异地多链。不把链表数据结构当本课。后课默认：要线性一致且写带宽不随 \\(n\\) 在主上爆炸，链是候选；要读扩展要想 CRAQ 或换 quorum。法定人数下一课从相交集合重新开始。</p><p>链的提交点几何上就是尾。改读位置就改一致性档。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>写从头到尾，读尾；尾是提交点。</li><li>中段故障靠配置主重链；配置面仍须强一致。</li><li>写带宽省在头，读集中在尾。</li><li>出处：van Renesse and Schneider, OSDI 2004。</li></ul>',10))])}const S=n(h,[["render",_]]);export{E as __pageData,S as default};
